from datetime import date; from decimal import Decimal; from uuid import uuid4; from src.extraction.orm.layer3 import ManagedPosition, PositionStatus; from src.ledger import Account, AccountType
class TestAssetsRouter:
    async def test_get_position_depreciation_success(self, client, db, test_user): 'AC-portfolio.depreciation.1 AC11.6.1'; account = Account(user_id=test_user.id, name='Test Broker', type=AccountType.ASSET, currency='USD'); db.add(account); await db.flush(); position = ManagedPosition(user_id=test_user.id, account_id=account.id, asset_identifier='AAPL', quantity=Decimal('10.0'), cost_basis=Decimal('1000.00'), acquisition_date=date(2024, 1, 1), status=PositionStatus.ACTIVE, currency='USD'); db.add(position); await db.commit(); await db.refresh(position); response = await client.get(f'/assets/positions/{position.id}/depreciation', params={'method': 'straight-line', 'useful_life_years': 5, 'salvage_value': '100.00'}); assert response.status_code == 200; data = response.json(); assert data['position_id'] == str(position.id); assert data['asset_identifier'] == 'AAPL'; assert data['method'] == 'straight-line'; assert data['useful_life_years'] == 5
    async def test_get_position_depreciation_not_found(self, client): 'AC-portfolio.depreciation.2 AC11.6.2'; fake_id = uuid4(); response = await client.get(f'/assets/positions/{fake_id}/depreciation', params={'method': 'straight-line', 'useful_life_years': 5}); assert response.status_code == 400; assert 'not found' in response.json()['detail'].lower()
    async def test_get_position_depreciation_disposed_position(self, client, db, test_user): 'AC-portfolio.depreciation.3 AC11.6.3'; account = Account(user_id=test_user.id, name='Test Broker', type=AccountType.ASSET, currency='USD'); db.add(account); await db.flush(); position = ManagedPosition(user_id=test_user.id, account_id=account.id, asset_identifier='AAPL', quantity=Decimal('0.0'), cost_basis=Decimal('0.00'), acquisition_date=date(2024, 1, 1), disposal_date=date(2024, 6, 1), status=PositionStatus.DISPOSED, currency='USD'); db.add(position); await db.commit(); await db.refresh(position); response = await client.get(f'/assets/positions/{position.id}/depreciation', params={'method': 'straight-line', 'useful_life_years': 5}); assert response.status_code == 400; assert 'disposed' in response.json()['detail'].lower()
    async def test_get_position_depreciation_invalid_params(self, client, db, test_user): 'AC-portfolio.depreciation.4 AC11.6.4'; account = Account(user_id=test_user.id, name='Test Broker', type=AccountType.ASSET, currency='USD'); db.add(account); await db.flush(); position = ManagedPosition(user_id=test_user.id, account_id=account.id, asset_identifier='AAPL', quantity=Decimal('10.0'), cost_basis=Decimal('1000.00'), acquisition_date=date(2024, 1, 1), status=PositionStatus.ACTIVE, currency='USD'); db.add(position); await db.commit(); await db.refresh(position); response = await client.get(f'/assets/positions/{position.id}/depreciation', params={'method': 'straight-line', 'useful_life_years': 0}); assert response.status_code == 422
